const SAMPLE_RATE = 16000;

let ws, audioCtx, micStream, processor, playbackNode;
let isListening = false;
let audioQueue = [];
let isPlaying = false;

const statusEl = document.getElementById('status');
const micEl = document.getElementById('mic');
const transcriptEl = document.getElementById('transcript');

async function init() {
  ws = new WebSocket(WS_URL);
  ws.binaryType = 'arraybuffer';

  ws.onopen = () => { statusEl.textContent = 'Connected'; };
  ws.onmessage = async (e) => {
    if (e.data instanceof ArrayBuffer) {
      queueAudio(new Int16Array(e.data));
    } else {
      const msg = JSON.parse(e.data);
      handleCommand(msg);
    }
  };
  ws.onclose = () => { statusEl.textContent = 'Disconnected'; };
}

function handleCommand(msg) {
  if (msg.type === 'state_change') {
    statusEl.textContent = msg.state === 'speaking' ? 'Companion speaking...' : 'Listening...';
    micEl.classList.toggle('active', msg.state === 'listening');
  }
  if (msg.type === 'transcript') {
    transcriptEl.textContent = msg.text;
  }
  if (msg.type === 'command' && msg.command === 'interrupt') {
    stopPlayback();
  }
}

async function startMic() {
  audioCtx = new AudioContext({ sampleRate: SAMPLE_RATE });
  micStream = await navigator.mediaDevices.getUserMedia({ audio: { sampleRate: SAMPLE_RATE, channelCount: 1 } });
  const source = audioCtx.createMediaStreamSource(micStream);
  processor = audioCtx.createScriptProcessor(4096, 1, 1);

  processor.onaudioprocess = (e) => {
    if (!isListening) return;
    const floatData = e.inputBuffer.getChannelData(0);
    const intData = new Int16Array(floatData.length);
    for (let i = 0; i < floatData.length; i++) {
      intData[i] = Math.max(-32768, Math.min(32767, floatData[i] * 32767));
    }
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(intData.buffer);
    }
  };

  source.connect(processor);
  processor.connect(audioCtx.destination);
  isListening = true;
  micEl.classList.add('active');
  statusEl.textContent = 'Listening...';
}

function stopMic() {
  isListening = false;
  if (processor) { processor.disconnect(); processor = null; }
  if (micStream) { micStream.getTracks().forEach(t => t.stop()); micStream = null; }
  micEl.classList.remove('active');
}

function queueAudio(pcmData) {
  audioQueue.push(pcmData);
  if (!isPlaying) playNext();
}

function playNext() {
  if (!audioQueue.length) { isPlaying = false; return; }
  isPlaying = true;
  const pcm = audioQueue.shift();
  const buffer = audioCtx.createBuffer(1, pcm.length, SAMPLE_RATE);
  const ch = buffer.getChannelData(0);
  for (let i = 0; i < pcm.length; i++) ch[i] = pcm[i] / 32768.0;

  playbackNode = audioCtx.createBufferSource();
  playbackNode.buffer = buffer;
  playbackNode.connect(audioCtx.destination);
  playbackNode.onended = playNext;
  playbackNode.start();
}

function stopPlayback() {
  if (playbackNode) { try { playbackNode.stop(); } catch(e) {} playbackNode = null; }
  audioQueue = [];
  isPlaying = false;
}

micEl.addEventListener('click', () => {
  if (!isListening) startMic(); else stopMic();
});

