            Folder = $_.DirectoryName.Replace($homeDir, "").TrimStart("\")
            FullPath = $_.FullName
            Hash = $null
        }
    }
}

# Quick hash check for obvious duplicates (same name + size)
$potentialDups = $allFiles | Group-Object Name, Size | Where-Object { $_.Count -gt 1 }
if ($potentialDups) {
