Get-ChildItem -Path $homeDir -Directory -Force | Where-Object {
    $name = $_.Name
    $isNew = $structure.Keys -contains $name
    $isSystem = $excludes -contains $name
    !$isNew -and !$isSystem
} | ForEach-Object {
    $isEmpty = !(Get-ChildItem -Path $_.FullName -Recurse -Force)
